package org.eclipse.kura.core.internal.linux.executor;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.UncheckedIOException;

import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteException;
import org.apache.commons.exec.ExecuteResultHandler;
import org.apache.commons.exec.ExecuteWatchdog;
import org.apache.commons.exec.Executor;
import org.eclipse.kura.core.linux.executor.LinuxExitStatus;
import org.eclipse.kura.core.linux.executor.LinuxResultHandler;
import org.eclipse.kura.executor.Command;
import org.eclipse.kura.executor.CommandStatus;
import org.junit.Test;

public class ExecutorUtilTimeoutTest {

    private static final int TIMEOUT_COMMAND_EXIT_VALUE = 124;
    private static final int SIGTERM_EXIT_VALUE = 143;

    private final DefaultExecutor executor = mock(DefaultExecutor.class);
    private final ExecutorUtil executorUtil = new ExecutorUtil() {

        @Override
        protected Executor getExecutor() {
            return ExecutorUtilTimeoutTest.this.executor;
        }
    };
    private final Command command = new Command(new String[] { "sleep", "10" });
    private CommandStatus status;

    @Test
    public void privilegedAsyncSigtermExitWithoutWatchdogKillIsNotTimedOut() {
        givenWatchdogKilledProcess(false);
        givenProcessExitsWith(SIGTERM_EXIT_VALUE);

        whenExecutedPrivilegedAsync();

        thenTimedOutIs(false);
    }

    @Test
    public void sigtermExitWithWatchdogKillIsTimedOut() {
        givenWatchdogKilledProcess(true);
        givenProcessExitsWith(SIGTERM_EXIT_VALUE);

        whenExecutedPrivileged();

        thenTimedOutIs(true);
    }

    @Test
    public void privilegedTimeoutExitWithoutWatchdogKillIsNotTimedOut() {
        givenWatchdogKilledProcess(false);
        givenProcessExitsWith(TIMEOUT_COMMAND_EXIT_VALUE);

        whenExecutedPrivileged();

        thenTimedOutIs(false);
    }

    @Test
    public void unprivilegedTimeoutExitWithoutWatchdogKillIsTimedOut() {
        givenWatchdogKilledProcess(false);
        givenProcessExitsWith(TIMEOUT_COMMAND_EXIT_VALUE);

        whenExecutedUnprivileged();

        thenTimedOutIs(true);
    }

    @Test
    public void unprivilegedAsyncTimeoutExitWithoutWatchdogKillIsTimedOut() {
        givenWatchdogKilledProcess(false);
        givenProcessExitsWith(TIMEOUT_COMMAND_EXIT_VALUE);

        whenExecutedUnprivilegedAsync();

        thenTimedOutIs(true);
    }

    @Test
    public void publicLinuxResultHandlerAppliesThePrivilegedRule() {
        givenWatchdogKilledProcess(false);

        whenLinuxResultHandlerReceivesExit(TIMEOUT_COMMAND_EXIT_VALUE);

        thenTimedOutIs(false);
    }

    private void givenWatchdogKilledProcess(boolean killed) {
        ExecuteWatchdog watchdog = mock(ExecuteWatchdog.class);
        when(watchdog.killedProcess()).thenReturn(killed);
        when(this.executor.getWatchdog()).thenReturn(watchdog);
    }

    private void givenProcessExitsWith(int exitValue) {
        ExecuteException failure = new ExecuteException("Process exited with an error: " + exitValue, exitValue);
        try {
            when(this.executor.execute(any(CommandLine.class))).thenThrow(failure);
            doAnswer(invocation -> {
                invocation.<ExecuteResultHandler> getArgument(1).onProcessFailed(failure);
                return null;
            }).when(this.executor).execute(any(CommandLine.class), any(ExecuteResultHandler.class));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void whenExecutedPrivileged() {
        this.status = this.executorUtil.executePrivileged(this.command);
    }

    private void whenExecutedUnprivileged() {
        this.status = this.executorUtil.executeUnprivileged(this.command);
    }

    private void whenExecutedPrivilegedAsync() {
        this.executorUtil.executePrivileged(this.command, result -> this.status = result);
    }

    private void whenExecutedUnprivilegedAsync() {
        this.executorUtil.executeUnprivileged(this.command, result -> this.status = result);
    }

    private void whenLinuxResultHandlerReceivesExit(int exitValue) {
        LinuxResultHandler handler = new LinuxResultHandler(result -> this.status = result, this.executor);
        handler.setStatus(new CommandStatus(this.command, new LinuxExitStatus(0)));
        handler.onProcessFailed(new ExecuteException("Process exited with an error: " + exitValue, exitValue));
    }

    private void thenTimedOutIs(boolean expected) {
        assertEquals(expected, this.status.isTimedout());
    }
}
